package org.securemail.client.ecosystemauth;

import com.google.gson.*;
import java.io.IOException;
import java.io.StringReader;
import com.google.gson.stream.*;
import java.security.MessageDigest;
import java.util.*;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;

/** Typed public exchange for the live Identity owner-transfer protocol. No root private key is accepted. */
public final class OwnerTransferFlow600 {
  private final IdentityClient600 client;private final CoreAccountSession600 session;
  public OwnerTransferFlow600(IdentityClient600 client,CoreAccountSession600 session){this.client=Objects.requireNonNull(client);this.session=Objects.requireNonNull(session);}
  public record Request(OwnerTransfer transfer,String requestId,long criticalExpiresAt){
    public Request{Objects.requireNonNull(transfer);IdentityProtocol.nonceValue(requestId);if(criticalExpiresAt<=0)throw new IllegalArgumentException("Invalid permit expiry");}
    public String encode(){return json("schema",1,"transfer",IdentityProtocol.b64(IdentityProtocol.ownerTransferBytes(transfer)),"requestId",requestId,"criticalExpiresAt",criticalExpiresAt).toString();}
    public static Request parse(String text)throws IOException{try{JsonObject o=parseObject(text,8192,Set.of("schema","transfer","requestId","criticalExpiresAt"));if(!schema(o))throw new IOException("Неподдерживаемый формат передачи владельца");return new Request(IdentityProtocol.decodeOwnerTransfer(IdentityProtocol.unb64(string(o,"transfer"),2048)),string(o,"requestId"),positive(o,"criticalExpiresAt"));}catch(IllegalArgumentException|IllegalStateException e){throw new IOException("Некорректный публичный запрос передачи владельца",e);}}
  }
  public record Consent(Request request,OwnerTransferRole role,byte[] rootPublic,byte[] devicePublic,byte[] rootProof,byte[] deviceProof){
    public Consent{Objects.requireNonNull(request);Objects.requireNonNull(role);rootPublic=rootPublic.clone();devicePublic=devicePublic.clone();rootProof=rootProof.clone();deviceProof=deviceProof.clone();IdentityProtocol.publicKey(rootPublic);IdentityProtocol.publicKey(devicePublic);OwnerTransfer t=request.transfer;boolean owner=role==OwnerTransferRole.OWNER_APPROVE;byte[] payload=IdentityProtocol.ownerTransferConsent(t,role);if(!IdentityProtocol.id(rootPublic).equals(owner?t.ownerAccountId:t.targetAccountId)||!IdentityProtocol.id(devicePublic).equals(owner?t.ownerDeviceId:t.targetDeviceId)||!IdentityProtocol.verify(rootPublic,payload,rootProof)||!IdentityProtocol.verify(devicePublic,payload,deviceProof))throw new IllegalArgumentException("Consent binding");}
    @Override public byte[] rootPublic(){return rootPublic.clone();}@Override public byte[] devicePublic(){return devicePublic.clone();}@Override public byte[] rootProof(){return rootProof.clone();}@Override public byte[] deviceProof(){return deviceProof.clone();}
    public String encode(){JsonObject o=json("schema",1,"request",request.encode(),"role",role.name(),"rootPublic",IdentityProtocol.b64(rootPublic),"devicePublic",IdentityProtocol.b64(devicePublic),"rootProof",IdentityProtocol.b64(rootProof),"deviceProof",IdentityProtocol.b64(deviceProof));return o.toString();}
    public static Consent parse(String text)throws IOException{try{JsonObject o=parseObject(text,16384,Set.of("schema","request","role","rootPublic","devicePublic","rootProof","deviceProof"));if(!schema(o))throw new IOException("Неподдерживаемое подтверждение");return new Consent(Request.parse(string(o,"request")),OwnerTransferRole.valueOf(string(o,"role")),IdentityProtocol.unb64(string(o,"rootPublic"),44),IdentityProtocol.unb64(string(o,"devicePublic"),44),IdentityProtocol.unb64(string(o,"rootProof"),64),IdentityProtocol.unb64(string(o,"deviceProof"),64));}catch(IllegalArgumentException|IllegalStateException e){throw new IOException("Некорректное подтверждение передачи владельца",e);}}
  }
  /** Caller first obtains Mail step-up. Server independently enforces current Owner and ADMIN. */
  public Request prepare(String target)throws IOException{
    live();IdentityProtocol.idValue(target);var grant=session.grant(App.AEGIS,Set.of(Scope.ACCOUNT_READ,Scope.ADMIN));long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] proposal=IdentityProtocol.ownerTransferProposal(client.audience(),session.accountId(),target,time,nonce);
    JsonObject answer=client.rpc("ownerTransferChallenge",signed(grant,"admin.execute",proposal,time,nonce,json("targetAccountId",target)));OwnerTransfer transfer=decode(answer);if(!transfer.ownerAccountId.equals(session.accountId())||!transfer.targetAccountId.equals(target))throw new IOException("Сервер вернул другую передачу владельца");
    time=System.currentTimeMillis();nonce=IdentityProtocol.nonce();byte[] payload=IdentityProtocol.ownerTransferBytes(transfer),approval=IdentityProtocol.criticalApproval(client.audience(),session.accountId(),"owner.transfer",nonce,payload,time+300_000);
    JsonObject permit=client.rpc("criticalRequest",signed(grant,"admin.execute",approval,time,nonce,json("operation","owner.transfer","payload",IdentityProtocol.b64(payload))));
    if(!string(permit,"operation").equals("owner.transfer")||!MessageDigest.isEqual(IdentityProtocol.unb64(string(permit,"payloadSha256"),32),IdentityProtocol.digest(payload)))throw new IOException("Разрешение относится к другой операции");live();return new Request(transfer,string(permit,"requestId"),positive(permit,"expiresAt"));
  }
  /** Live signed inspection is mandatory before a participant's Mail consent. */
  public OwnerTransfer inspect(Request request)throws IOException{
    valid(request);var grant=session.grant(App.AEGIS,Set.of(Scope.ACCOUNT_READ));long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] body=IdentityProtocol.ownerTransferInspection(client.audience(),request.transfer.challenge,time,nonce);
    OwnerTransfer actual=decode(client.rpc("ownerTransferInspect",signed(grant,"account.read",body,time,nonce,json("challenge",request.transfer.challenge))));if(!MessageDigest.isEqual(IdentityProtocol.ownerTransferBytes(actual),IdentityProtocol.ownerTransferBytes(request.transfer)))throw new IOException("Запрос передачи владельца изменён");live();return actual;
  }
  /** Root proof comes only from separately authenticated Mail typed consent. */
  public Consent consent(Request request,OwnerTransferRole role,byte[] rootProof)throws IOException{inspect(request);try{return new Consent(request,role,session.accountPublic(),session.devicePublic(),rootProof,session.signOwnerTransferConsent(request.transfer,role));}catch(IllegalArgumentException invalid){throw new IOException("Почта не подтвердила передачу владельца",invalid);}}
  /** A distinct existing administrator explicitly approves these exact canonical transfer bytes. */
  public void approve(Request request)throws IOException{valid(request);var grant=session.grant(App.AEGIS,Set.of(Scope.ACCOUNT_READ,Scope.ADMIN));long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] body=IdentityProtocol.criticalApproval(client.audience(),session.accountId(),"owner.transfer",request.requestId,IdentityProtocol.ownerTransferBytes(request.transfer),request.criticalExpiresAt);JsonObject answer=client.rpc("criticalApprove",signed(grant,"admin.execute",body,time,nonce,json("requestId",request.requestId)));if(!bool(answer,"approved"))throw new IOException("Подтверждение администратора отклонено");live();}
  public void complete(Consent owner,Consent successor)throws IOException{
    Request request=owner.request;valid(request);if(owner.role!=OwnerTransferRole.OWNER_APPROVE||successor.role!=OwnerTransferRole.SUCCESSOR_ACCEPT||!owner.request.encode().equals(successor.request.encode())||!session.accountId().equals(request.transfer.ownerAccountId))throw new IOException("Подтверждения относятся к разным операциям");inspect(request);var grant=session.grant(App.AEGIS,Set.of(Scope.ACCOUNT_READ,Scope.ADMIN));long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] body=IdentityProtocol.criticalApproval(client.audience(),session.accountId(),"owner.transfer",request.requestId,IdentityProtocol.ownerTransferBytes(request.transfer),request.criticalExpiresAt);
    JsonObject args=json("challenge",request.transfer.challenge,"requestId",request.requestId,"ownerRootProof",IdentityProtocol.b64(owner.rootProof),"ownerDeviceProof",IdentityProtocol.b64(owner.deviceProof),"targetRootProof",IdentityProtocol.b64(successor.rootProof),"targetDeviceProof",IdentityProtocol.b64(successor.deviceProof));JsonObject answer=client.rpc("ownerTransferComplete",signed(grant,"admin.execute",body,time,nonce,args));if(!bool(answer,"transferred")||!bool(answer,"sessionsRevoked"))throw new IOException("Передача владельца не подтверждена");session.lock();
  }
  private OwnerTransfer decode(JsonObject answer)throws IOException{try{OwnerTransfer t=IdentityProtocol.decodeOwnerTransfer(IdentityProtocol.unb64(string(answer,"transfer"),2048));if(!t.audience.equals(client.audience())||t.expiresAt<=System.currentTimeMillis()||t.expiresAt>System.currentTimeMillis()+120_000)throw new IOException("Подтверждение передачи истекло");return t;}catch(IllegalArgumentException invalid){throw new IOException("Некорректный ответ о передаче владельца",invalid);}}
  private void valid(Request request)throws IOException{live();long now=System.currentTimeMillis();if(!request.transfer.audience.equals(client.audience())||request.transfer.expiresAt<=now||request.transfer.expiresAt>now+120_000||request.criticalExpiresAt<=now||request.criticalExpiresAt>now+300_000)throw new IOException("Запрос передачи владельца истёк");}
  private void live()throws IOException{if(session.locked())throw new IOException("Сессия АЕГИС заблокирована");session.coreGrant();}
  static JsonObject signed(CoreAccountSession600.AppGrant grant,String action,byte[] body,long time,String nonce,JsonObject args){args.addProperty("capability",grant.wire());args.addProperty("time",time);args.addProperty("nonce",nonce);args.addProperty("proof",IdentityProtocol.b64(IdentityProtocol.sign(grant.proofPrivate(),IdentityProtocol.requestDigest(grant.capability(),action,IdentityProtocol.digest(body),time,nonce))));return args;}
  static JsonObject parseObject(String text,int maximum,Set<String> fields)throws IOException{
    if(text==null||text.length()>maximum)throw new IOException("Слишком большой публичный код");JsonObject value=new JsonObject();
    try(JsonReader reader=new JsonReader(new StringReader(text))){reader.setStrictness(Strictness.STRICT);reader.beginObject();while(reader.hasNext()){String field=reader.nextName();if(!fields.contains(field)||value.has(field))throw new IOException("Повторное или неожиданное поле публичного кода");JsonToken token=reader.peek();if(token==JsonToken.STRING)value.addProperty(field,reader.nextString());else if(token==JsonToken.NUMBER){String number=reader.nextString();if(!number.matches("[1-9][0-9]{0,18}"))throw new IOException("Некорректное число публичного кода");try{value.addProperty(field,Long.parseLong(number));}catch(NumberFormatException invalid){throw new IOException("Слишком большое число публичного кода",invalid);}}else throw new IOException("Неожиданный тип поля публичного кода");}reader.endObject();if(reader.peek()!=JsonToken.END_DOCUMENT||!value.keySet().equals(fields))throw new IOException("Некорректные поля публичного кода");return value;}catch(IllegalStateException|JsonParseException bad){throw new IOException("Некорректный публичный код",bad);}
  }
  static boolean schema(JsonObject o){JsonElement v=o.get("schema");return v!=null&&v.isJsonPrimitive()&&v.getAsJsonPrimitive().isNumber()&&v.getAsString().equals("1");}
  static boolean bool(JsonObject o,String key)throws IOException{JsonElement v=o.get(key);if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isBoolean())throw new IOException("Некорректный ответ сервера");return v.getAsBoolean();}
  static long positive(JsonObject o,String key)throws IOException{JsonElement v=o.get(key);if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isNumber()||!v.getAsString().matches("[1-9][0-9]{0,18}"))throw new IOException("Некорректный срок разрешения");try{return Long.parseLong(v.getAsString());}catch(NumberFormatException invalid){throw new IOException("Некорректный срок разрешения",invalid);}}
  static String string(JsonObject o,String key)throws IOException{JsonElement v=o.get(key);if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isString())throw new IOException("Некорректный публичный код");return v.getAsString();}
  static JsonObject json(Object... pairs){JsonObject o=new JsonObject();for(int i=0;i<pairs.length;i+=2){Object v=pairs[i+1];if(v instanceof Number n)o.addProperty((String)pairs[i],n);else o.addProperty((String)pairs[i],v.toString());}return o;}
}
